// Fine-liner figures for Chapter 06, HDR photography. Adapted from the LumiSnap field guide
// (lumisnap.io/guide.html) and redrawn with the ink kit of Chapters 02–05: white surfaces,
// hatched cut walls and clipped ranges, pencil construction lines. Luminance is drawn in the
// ALT blue, illuminance in the AZI cyan. Generated by scripts/generate-hdr.mjs.
import { svgDocument } from './svg.js';
import { inkKit as kit, PEN } from './ink.js';
import { turbo } from './palette.js';
import { DESIGN_FIGURES } from './hdr-design-figures.js';

const IMG = './assets/hdr/';

/** Lines of text, one below the other. */
const lines = (k, x, y, arr, o = {}) => arr.map((t, i) => k.text(x, y + i * (o.step ?? 18), t, { size: 12, ...o })).join('');
/** Arrow in a coloured pencil, as for the angles in Chapters 02–05. */
const ray = (k, a, b, colour, name) => k.line(a, b, { stroke: colour, width: 1.4, arrow: name });

/** A camera on a tripod in section, lens toward +x. Returns the lens centre too. */
function tripod(k, x, floor, lensY) {
  const c = k.c;
  let g = k.rect(x - 22, lensY - 13, 34, 26, { fill: c.paper, stroke: c.ink, width: PEN.outline });
  g += k.rect(x + 12, lensY - 9, 9, 18, { fill: c.shadow, stroke: c.ink, width: PEN.edge });
  for (const dx of [-34, 0, 34]) g += k.line({ x: x - 5, y: lensY + 14 }, { x: x - 5 + dx, y: floor }, { stroke: c.ink, width: PEN.edge });
  return { g, lens: { x: x + 21, y: lensY } };
}

/* 01 · Illuminance and luminance in one room */
export function figQuantities(standalone = false) {
  const k = kit(standalone, 'hq'), c = k.c, floor = 380, ceil = 90;
  let room = k.rect(40, ceil - 14, 900, 14, { fill: c.shadow }) + k.rect(40, floor, 900, 14, { fill: c.shadow });
  room += k.rect(40, ceil, 20, 70, { fill: c.shadow }) + k.rect(40, 300, 20, floor - 300, { fill: c.shadow }) + k.rect(46, 160, 8, 140, { fill: c.glass, stroke: c.ink, width: PEN.edge });
  room += k.rect(920, ceil, 20, floor - ceil, { fill: c.shadow });
  // Desk with an upward-facing lux sensor.
  room += k.rect(190, 292, 260, 9, { fill: c.paper, stroke: c.ink, width: PEN.outline }) + k.line({ x: 200, y: 301 }, { x: 200, y: floor }, { width: PEN.outline }) + k.line({ x: 440, y: 301 }, { x: 440, y: floor }, { width: PEN.outline });
  room += k.rect(300, 282, 34, 10, { fill: c.paper, stroke: c.ink, width: PEN.edge }) + k.arc(317, 282, 9, 0, 180, { stroke: c.ink, width: PEN.edge });
  // Daylight arriving on the desk.
  let e = '';
  for (const [a, b] of [[{ x: 14, y: 160 }, { x: 300, y: 276 }], [{ x: 14, y: 196 }, { x: 316, y: 270 }], [{ x: 14, y: 232 }, { x: 330, y: 276 }]]) e += ray(k, a, b, c.azi, 'azi');
  e += k.label(140, 132, 'ILLUMINANCE  E  [lx]', { size: 12, weight: 700, fill: c.azi }) + lines(k, 140, 150, ['Light arriving on a plane,', 'from every direction above it.'], { fill: c.ink, step: 16 });
  e += lines(k, 210, 330, ['Lux sensor on the desk,', 'diffuser facing up.'], { size: 11, step: 15 });
  // Camera reading a wall patch.
  const cam = tripod(k, 640, floor, 220);
  let l = cam.g + k.rect(913, 170, 7, 70, { fill: c.paper, stroke: c.alt, width: 2.2 });
  for (const y of [178, 205, 232]) l += ray(k, { x: 910, y }, { x: cam.lens.x + 8, y: cam.lens.y + (y - 205) * .12 }, c.alt, 'alt');
  l += k.line(cam.lens, { x: 912, y: 112 }, { stroke: c.axis, dash: '4 4' }) + k.line(cam.lens, { x: 912, y: 330 }, { stroke: c.axis, dash: '4 4' });
  l += k.label(700, 132, 'LUMINANCE  L  [cd/m²]', { size: 12, weight: 700, fill: c.alt }) + lines(k, 700, 150, ['Light leaving one surface', 'toward the lens or the eye.'], { fill: c.ink, step: 16 });
  l += lines(k, 680, 300, ['A calibrated HDR records L', 'for every pixel of the view.'], { size: 11, step: 15 });
  const note = k.text(40, 425, 'The same daylight gives one E on the desk, but a different L for each surface, depending on its reflectance and the direction of view.', { size: 12 });
  return svgDocument(k, { width: 980, height: 440, title: 'Illuminance on a desk and luminance of a wall seen by a camera', body: k.group('room', room) + k.group('illuminance', e) + k.group('luminance', l) + k.group('note', note) });
}

/* 02 · Camera position: plan and section */
export function figCaptureSetup(standalone = false) {
  const k = kit(standalone, 'hcs'), c = k.c;
  // A: plan. View toward the window wall (up the page).
  let plan = k.title(40, 36, 'A · Plan: the view in front of the observer');
  plan += k.rect(60, 70, 400, 14, { fill: c.shadow }) + k.rect(160, 70, 200, 14, { fill: c.glass, stroke: c.ink, width: PEN.edge });
  plan += k.rect(60, 84, 14, 330, { fill: c.shadow }) + k.rect(446, 84, 14, 330, { fill: c.shadow }) + k.rect(60, 414, 400, 14, { fill: c.shadow });
  const C = { x: 260, y: 330 };
  plan += k.path(`M${C.x - 170},${C.y} A170,170 0 0 1 ${C.x + 170},${C.y} Z`, { fill: c.glass, stroke: 'none' });
  plan += k.arc(C.x, C.y, 170, 180, 0, { stroke: c.ink, width: PEN.edge, dash: '7 5' }) + k.line({ x: C.x - 170, y: C.y }, { x: C.x + 170, y: C.y }, { stroke: c.axis, dash: '4 4' });
  plan += k.rect(C.x - 18, C.y - 6, 36, 26, { fill: c.paper, stroke: c.ink, width: PEN.outline }) + k.circle({ x: C.x, y: C.y - 6 }, 10, { fill: c.paper, stroke: c.ink, width: PEN.outline });
  plan += k.line({ x: C.x, y: C.y - 22 }, { x: C.x, y: 190 }, { stroke: c.ink, width: PEN.outline, arrow: 'ink' }) + k.label(C.x + 8, 214, 'view direction', { size: 12, fill: c.ink });
  plan += k.label(C.x, C.y + 42, 'Lens at the observer position', { size: 12, anchor: 'middle', fill: c.ink }) + k.label(C.x, C.y + 58, '180° in plan; the full forward hemisphere in 3D', { size: 11, anchor: 'middle' });
  plan += k.circle({ x: 120, y: 240 }, 13, { fill: c.paper, stroke: c.alt, width: 2.2 }) + k.label(120, 274, 'matte target', { size: 11, anchor: 'middle', fill: c.alt });
  plan += k.text(260, 104, 'WINDOW', { size: 10, anchor: 'middle', weight: 700, spacing: 1.2, fill: c.ink });
  // B: section. Lens at eye height, level axis.
  const floor = 414, x0 = 540;
  let sec = k.title(x0, 36, 'B · Section: the lens at eye height');
  sec += k.rect(x0, floor, 420, 14, { fill: c.shadow }) + k.rect(x0, 70, 420, 14, { fill: c.shadow }) + k.rect(946, 84, 14, 110, { fill: c.shadow }) + k.rect(946, 300, 14, floor - 300, { fill: c.shadow }) + k.rect(950, 194, 6, 106, { fill: c.glass, stroke: c.ink, width: PEN.edge });
  const eye = floor - 120, cam = tripod(k, 700, floor, eye);
  sec += cam.g + k.line(cam.lens, { x: 930, y: eye }, { stroke: c.ink, width: PEN.outline, arrow: 'ink' }) + k.label(800, eye - 10, 'level axis', { size: 12, fill: c.ink });
  // Lux sensor beside the lens, vertical, facing the view.
  sec += k.rect(722, eye + 18, 6, 22, { fill: c.paper, stroke: c.azi, width: 2 }) + k.line({ x: 725, y: eye + 40 }, { x: 712, y: eye + 54 }, { stroke: c.azi, width: 1.2 });
  sec += lines(k, 740, eye + 34, ['Lux sensor: same position,', 'vertical, facing the view'], { size: 11, step: 15, fill: c.azi });
  sec += k.line({ x: 600, y: floor }, { x: 600, y: eye }, { stroke: c.alt, width: 1.4, arrow: 'alt' }) + k.line({ x: 592, y: eye }, { x: 608, y: eye }, { stroke: c.alt, width: 1.4 });
  sec += k.label(608, (floor + eye) / 2 + 4, 'eye height', { size: 12, fill: c.alt, weight: 600 }) + lines(k, 556, 120, ['Use the real eye height:', 'about 1.2 m seated, 1.6 m standing.', 'Record it with the capture.'], { step: 16 });
  const note = lines(k, 40, 468, ['Keep the operator behind the lens during capture. Record location, date, time, view direction and sky conditions.', 'In a scale model, place the lens at the equivalent eye position and keep the camera opening from blocking daylight.'], { step: 18 });
  return svgDocument(k, { width: 1000, height: 510, title: 'Camera setup for a lighting study, in plan and section', body: k.group('plan', plan) + k.group('section', sec) + k.group('note', note) });
}

/* 03 · Overlapping exposures */
export function figExposureOverlap(standalone = false) {
  const k = kit(standalone, 'hex'), c = k.c, x0 = 230, x1 = 930, h = 30;
  let axis = k.line({ x: x0, y: 72 }, { x: x1 + 10, y: 72 }, { stroke: c.ink, width: PEN.outline, arrow: 'ink' });
  axis += k.text(x0, 60, 'darker surfaces', { size: 12, fill: c.ink }) + k.text(x1, 60, 'brighter sources', { size: 12, anchor: 'end', fill: c.ink });
  axis += k.text(x0 + (x1 - x0) / 2, 60, 'scene luminance, log scale', { size: 11, anchor: 'middle' });
  for (let i = 0; i <= 10; i++) { const x = x0 + i * (x1 - x0) / 10; axis += k.line({ x, y: 68 }, { x, y: 76 }, { stroke: c.ink, width: PEN.edge }); }
  // Each bar: noise (cross-direction hatch), usable signal (paper), clipped (dense hatch).
  const bar = (y, [a, b], name, sub) => {
    let g = k.text(40, y + 13, name, { size: 13, weight: 700, fill: c.ink }) + k.text(40, y + 29, sub, { size: 11 });
    if (a > x0) g += k.rect(x0, y, a - x0, h, { fill: c.glass, stroke: c.ink, width: PEN.hatch });
    g += k.rect(a, y, b - a, h, { fill: c.paper, stroke: c.ink, width: PEN.outline }) + k.text((a + b) / 2, y + 20, 'usable signal', { size: 12, anchor: 'middle', fill: c.ink });
    if (b < x1) g += k.rect(b, y, x1 - b, h, { fill: c.shadow });
    return g;
  };
  const bars = [[110, [x0, 520], 'Long exposure', 'e.g. 1/30 s'], [180, [370, 690], 'Middle exposure', 'e.g. 1/125 s · 2 stops shorter'], [250, [540, 860], 'Short exposure', 'e.g. 1/500 s · 2 stops shorter']];
  let g = bars.map(([y, r, n, s]) => bar(y, r, n, s)).join('');
  // Overlaps.
  for (const [a, b, y] of [[370, 520, 140], [540, 690, 210]]) g += k.line({ x: a, y: y + 2 }, { x: a, y: y + 38 }, { stroke: c.third, width: 1.2, dash: '3 3' }) + k.line({ x: b, y: y + 2 }, { x: b, y: y + 38 }, { stroke: c.third, width: 1.2, dash: '3 3' }) + k.label((a + b) / 2, y + 25, 'overlap', { size: 11, anchor: 'middle', fill: c.third, weight: 600 });
  // Merge.
  let m = k.text(40, 353, 'Merged HDR', { size: 13, weight: 700, fill: c.ink }) + k.text(40, 369, 'one linear image', { size: 11 });
  m += k.rect(x0, 340, 860 - x0, h, { fill: c.paper, stroke: c.ink, width: PEN.profile }) + k.text((x0 + 860) / 2, 360, 'ratios preserved → calibrate to cd/m²', { size: 12, anchor: 'middle', fill: c.ink, weight: 600 });
  m += k.rect(860, 340, x1 - 860, h, { fill: c.shadow }) + k.line({ x: 895, y: 340 }, { x: 895, y: 312 }, { stroke: c.red, width: 1.4 }) + k.label(895, 304, 'clipped in every frame: unknown', { size: 11, anchor: 'end', fill: c.red, weight: 600 });
  // Key.
  let key = '';
  [[c.glass, 'below the noise floor'], [c.paper, 'usable signal'], [c.shadow, 'clipped (saturated)']].forEach(([fill, t], i) => { const x = 40 + i * 210; key += k.rect(x, 404, 26, 14, { fill, stroke: c.ink, width: PEN.hatch }) + k.text(x + 34, 415, t, { size: 11.5, fill: c.ink }); });
  key += k.text(40, 448, 'Conceptual ranges. Each important area needs one frame above noise and below clipping; the frame count follows from coverage.', { size: 11.5 });
  return svgDocument(k, { width: 980, height: 465, title: 'Exposure bracket: overlapping usable ranges merge into one linear HDR', body: k.group('axis', axis) + k.group('exposures', g) + k.group('merge', m) + k.group('key', key) });
}

/* 04 · Two meters, two units */
export function figMeters(standalone = false) {
  const k = kit(standalone, 'hm'), c = k.c;
  // A: illuminance meter, after the Konica Minolta T-10A.
  let a = k.title(40, 36, 'A · Illuminance meter') + k.text(40, 56, 'e.g. Konica Minolta T-10A', { size: 12 });
  a += k.text(40, 96, 'lx', { size: 34, weight: 700, fill: c.azi });
  const X = 250;
  a += k.rect(X - 42, 150, 84, 170, { fill: c.paper, stroke: c.ink, width: PEN.outline, rx: 10 });
  a += k.circle({ x: X, y: 136 }, 38, { fill: c.face, stroke: c.ink, width: PEN.outline }) + k.circle({ x: X, y: 136 }, 24, { fill: c.paper, stroke: c.ink, width: PEN.edge });
  a += k.rect(X - 32, 180, 64, 40, { fill: c.paper, stroke: c.ink, width: PEN.edge }) + k.text(X + 10, 207, '500', { size: 17, anchor: 'end', fill: c.ink }) + k.text(X + 14, 207, 'lx', { size: 10, fill: c.ink });
  for (const dx of [-26, -6, 14]) a += k.rect(X + dx, 232, 14, 7, { stroke: c.ink, width: PEN.hatch, fill: c.paper });
  a += k.rect(X - 32, 252, 64, 22, { fill: c.shadow });
  a += k.line({ x: 150, y: 120 }, { x: X - 22, y: 132 }, { stroke: c.ink, width: PEN.hatch }) + lines(k, 60, 112, ['white diffuser', 'collects light'], { size: 11.5, fill: c.ink, step: 15 });
  a += k.line({ x: 150, y: 200 }, { x: X - 34, y: 200 }, { stroke: c.ink, width: PEN.hatch }) + k.text(60, 204, 'reads lux', { size: 11.5, fill: c.ink });
  a += k.text(X + 58, 170, 'no viewfinder', { size: 11.5, fill: c.ink });
  a += k.text(40, 360, 'LIGHT ARRIVING AT A PLANE', { size: 12, weight: 700, spacing: 1, fill: c.azi }) + lines(k, 40, 380, ['How much light reaches this position?', 'PLACE the sensor on the measurement plane:', '· desk: diffuser faces up', '· eye plane: diffuser faces the view direction', 'Use: workplane E or eye illuminance Ev.'], { fill: c.ink });
  // B: luminance meter, after the Konica Minolta LS-150.
  let b = k.title(520, 36, 'B · Spot luminance meter') + k.text(520, 56, 'e.g. Konica Minolta LS-150', { size: 12 });
  b += k.text(520, 96, 'cd/m²', { size: 34, weight: 700, fill: c.alt });
  const body = 'M 0 0 H 148 Q 179 0 179 28 V 96 Q 179 122 153 125 L 116 128 L 99 239 H 47 L 59 129 H 7 Q -17 129 -17 105 V 25 Q -17 0 0 0 Z';
  let m = k.path(body, { fill: c.paper, stroke: c.ink, width: PEN.outline });
  m += k.rect(-41, 38, 25, 43, { fill: c.shadow }) + k.rect(178, 15, 62, 96, { fill: c.face, stroke: c.ink, width: PEN.outline }) + k.rect(212, 15, 28, 96, { fill: c.shadow });
  m += k.text(20, 42, 'LS-150', { size: 16, weight: 700, fill: c.ink }) + k.line({ x: 7, y: 57 }, { x: 151, y: 57 }, { stroke: c.ink, width: PEN.hatch }) + k.line({ x: 60, y: 211 }, { x: 93, y: 211 }, { stroke: c.ink, width: PEN.hatch });
  b += `<g transform="translate(640 110)">${m}</g>`;
  b += k.line({ x: 570, y: 222 }, { x: 604, y: 194 }, { stroke: c.ink, width: PEN.hatch }) + k.text(520, 238, 'viewfinder: look here', { size: 11.5, fill: c.ink });
  b += k.line({ x: 850, y: 108 }, { x: 850, y: 123 }, { stroke: c.ink, width: PEN.hatch }) + k.text(850, 100, 'lens: aim at a patch', { size: 11.5, anchor: 'middle', fill: c.ink });
  // Measuring cone to a patch.
  b += k.line({ x: 880, y: 170 }, { x: 960, y: 160 }, { stroke: c.alt, width: 1 }) + k.line({ x: 880, y: 170 }, { x: 960, y: 180 }, { stroke: c.alt, width: 1 }) + k.text(958, 205, '1° spot', { size: 11, anchor: 'end', fill: c.alt, weight: 600 });
  b += k.rect(800, 270, 120, 46, { fill: c.paper, stroke: c.ink, width: PEN.edge }) + k.text(866, 300, '150', { size: 17, anchor: 'end', fill: c.ink }) + k.text(870, 300, 'cd/m²', { size: 10, fill: c.ink }) + k.text(800, 332, 'rear display (example)', { size: 10.5 });
  b += k.text(520, 360, 'LIGHT FROM A SELECTED PATCH', { size: 12, weight: 700, spacing: 1, fill: c.alt }) + lines(k, 520, 380, ['How bright is that surface from here?', 'AIM the lens through the viewfinder:', '· keep the central circle on one patch', '· the spot is 1°, not the whole viewfinder', 'Use: spot readings for HDR calibration.'], { fill: c.ink });
  const div = k.line({ x: 490, y: 24 }, { x: 490, y: 470 }, { stroke: c.axis, dash: '3 4' });
  const note = k.text(40, 500, 'Only cd/m² spot readings belong in an HDR calibration. Simplified drawings; the display values are examples, not a lux-to-cd/m² conversion.', { size: 12 });
  return svgDocument(k, { width: 990, height: 515, title: 'An illuminance meter reads lux on a plane; a spot luminance meter reads cd/m² from a patch', body: k.group('illuminance-meter', a) + k.group('luminance-meter', b) + k.group('divider', div) + k.group('note', note) });
}

/* 05 · Three measurements, three questions */
export function figMethods(standalone = false) {
  const k = kit(standalone, 'hmm'), c = k.c, floor = 250;
  const panel = (x, title, unit, colour, notes, use) => k.title(x, 36, title) + k.text(x, 64, unit, { size: 20, weight: 700, fill: colour }) + lines(k, x, 290, notes, { fill: c.ink }) + k.text(x, 372, use, { size: 12, weight: 600, fill: colour });
  // A: spot luminance.
  let a = panel(30, 'A · Spot luminance', 'L  cd/m²', c.alt, ['Aim from near the lens position.', 'Keep the whole spot inside one', 'uniform matte surface. Repeat', 'on several targets.'], 'Sets the image scale.');
  a += k.rect(40, 130, 46, 24, { fill: c.paper, stroke: c.ink, width: PEN.outline }) + k.rect(86, 134, 14, 16, { fill: c.shadow }) + k.line({ x: 60, y: 154 }, { x: 60, y: floor }, { stroke: c.ink, width: PEN.edge });
  a += k.polygon([{ x: 100, y: 142 }, { x: 250, y: 124 }, { x: 250, y: 160 }], { fill: c.paper, stroke: c.alt, width: 1 });
  a += k.rect(250, 100, 18, 84, { fill: c.paper, stroke: c.alt, width: 2.2 }) + k.rect(268, 80, 10, floor - 80, { fill: c.shadow });
  a += k.label(250, 205, 'matte target', { size: 11, anchor: 'end', fill: c.alt });
  // B: vertical eye illuminance.
  let b = panel(350, 'B · Eye illuminance', 'Ev  lx', c.azi, ['Sensor vertical at the lens, facing', 'the view direction. Do not shade', 'it. Read before and after the', 'bracket.'], 'Checks the hemispheric total.');
  b += k.rect(430, 120, 9, 50, { fill: c.paper, stroke: c.ink, width: PEN.outline }) + k.line({ x: 434, y: 170 }, { x: 434, y: floor }, { stroke: c.ink, width: PEN.edge });
  for (const [x, y] of [[600, 90], [620, 145], [600, 200]]) b += ray(k, { x, y }, { x: 446, y: 145 + (y - 145) * .3 }, c.azi, 'azi');
  b += k.label(560, 80, 'incoming light', { size: 11, anchor: 'middle', fill: c.azi });
  // C: workplane illuminance.
  let cc = panel(670, 'C · Workplane illuminance', 'E  lx', c.azi, ['Sensor horizontal, facing up, on', 'a documented grid at the desk or', 'model workplane. Record its', 'height and positions.'], 'Tests daylight reaching the task.');
  cc += k.rect(690, 200, 260, 8, { fill: c.paper, stroke: c.ink, width: PEN.outline }) + k.line({ x: 700, y: 208 }, { x: 700, y: floor }, { width: PEN.outline }) + k.line({ x: 940, y: 208 }, { x: 940, y: floor }, { width: PEN.outline });
  cc += k.rect(800, 191, 40, 9, { fill: c.paper, stroke: c.ink, width: PEN.edge });
  for (const [x, y] of [[760, 100], [820, 90], [880, 100]]) cc += ray(k, { x, y }, { x: 820 + (x - 820) * .12, y: 186 }, c.azi, 'azi');
  let ground = '';
  for (const [x0, x1] of [[30, 300], [350, 630], [670, 960]]) ground += k.line({ x: x0, y: floor }, { x: x1, y: floor }, { stroke: c.ink, width: PEN.profile });
  ground += k.line({ x: 325, y: 24 }, { x: 325, y: 380 }, { stroke: c.axis, dash: '3 4' }) + k.line({ x: 650, y: 24 }, { x: 650, y: 380 }, { stroke: c.axis, dash: '3 4' });
  const note = k.text(30, 412, 'A lux reading cannot go into a cd/m² calibration field. Match each reading to its image, position, orientation and time.', { size: 12 });
  return svgDocument(k, { width: 990, height: 425, title: 'Three measurements: spot luminance, eye illuminance and workplane illuminance', body: k.group('spot-luminance', a) + k.group('eye-illuminance', b) + k.group('workplane-illuminance', cc) + k.group('ground', ground) + k.group('note', note) });
}

/* 06 · Matching readings to image regions, on the supplied portrait capture */
export const CALIBRATION_TARGETS = [['A', .384, .795, 67, 'timber floor'], ['B', .072, .705, 165, 'timber floor'], ['C', .326, .546, 77, 'painted wall'], ['D', .466, .541, 415, 'painted wall'], ['E', .666, .123, 65, 'ceiling panel']];
export function figCalibration(standalone = false, href = null) {
  const k = kit(standalone, 'hcal'), c = k.c, X = 30, Y = 40, W = 380, H = W * 1349 / 900;
  const src = href ?? (standalone ? '../../hdr/portrait-2043.jpg' : `${IMG}portrait-2043.webp`);
  let photo = `<image x="${X}" y="${Y}" width="${W}" height="${H.toFixed(1)}" href="${src}" preserveAspectRatio="xMidYMid slice"/>` + k.rect(X, Y, W, H, { stroke: c.ink, width: PEN.outline });
  let marks = '', list = k.title(460, 52, 'Spot readings, same capture');
  CALIBRATION_TARGETS.forEach(([id, px, py, value, material], i) => {
    const p = { x: X + px * W, y: Y + py * H };
    marks += `<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="12" fill="none" stroke="#ffffff" stroke-width="4"/>` + k.circle(p, 12, { stroke: c.ink, width: PEN.outline });
    marks += `<circle cx="${(p.x + 22).toFixed(1)}" cy="${(p.y - 14).toFixed(1)}" r="11" fill="#ffffff" stroke="#26333e" stroke-width="1.2"/><text x="${(p.x + 22).toFixed(1)}" y="${(p.y - 10).toFixed(1)}" font-size="12" font-weight="700" fill="#26333e" text-anchor="middle">${id}</text>`;
    const y = 90 + i * 56;
    list += k.line({ x: 460, y: y - 22 }, { x: 960, y: y - 22 }, { stroke: c.grid }) + k.text(460, y + 6, id, { size: 22, weight: 700, fill: c.alt });
    list += k.text(500, y, `${value} cd/m²`, { size: 16, weight: 700, fill: c.ink }) + k.text(500, y + 18, material, { size: 12 });
  });
  list += k.line({ x: 460, y: 90 + 5 * 56 - 22 }, { x: 960, y: 90 + 5 * 56 - 22 }, { stroke: c.grid });
  list += lines(k, 460, 390, ['Choose matte, evenly lit patches that the meter spot fills.', 'Cover darker and brighter surfaces (here 65–415 cd/m²).', 'Avoid edges, gloss, shadows and clipped pixels.', 'Keep one target out of the fit as an independent check.'], { fill: c.ink });
  list += lines(k, 460, 486, ['Course notes: Oct 5, 2026, 4:30 pm. Photo EXIF: 4:45:53 pm.', 'The times differ, so these readings illustrate target', 'selection; they are not a validated calibration of this frame.', 'Marker positions are approximate.'], { size: 11.5 });
  return svgDocument(k, { width: 980, height: Math.ceil(Y + H + 30), title: 'Portrait capture with five spot-luminance targets', body: k.group('photo', photo) + k.group('targets', marks) + k.group('readings', list) });
}

/* 07 · From exposures to evidence */
export function figWorkflow(standalone = false) {
  const k = kit(standalone, 'hwf'), c = k.c, w = 280, h = 132;
  const box = (x, y, title, body, o = {}) => k.rect(x, y, o.w ?? w, o.h ?? h, { fill: c.paper, stroke: c.ink, width: o.pen ?? PEN.outline }) + k.title(x + 16, y + 28, title, { fill: o.colour ?? c.ink }) + lines(k, x + 16, y + 54, body, { fill: c.ink });
  let g = box(30, 30, '1 · Merge', ['Read the exposure metadata.', 'Align the frames; undo the', 'JPEG response curve.']);
  g += box(355, 30, '2 · Lens', ['Set projection and field of view.', 'Check the image circle.', 'Apply measured vignetting.']);
  g += box(680, 30, '3 · Calibrate', ['Select the measured targets.', 'Enter spot readings in cd/m².', 'Inspect the fit and residuals.'], { colour: c.alt });
  g += k.line({ x: 314, y: 96 }, { x: 350, y: 96 }, { width: PEN.outline, arrow: 'ink' }) + k.line({ x: 639, y: 96 }, { x: 675, y: 96 }, { width: PEN.outline, arrow: 'ink' });
  g += k.path('M820,166 V196 H490 V222', { stroke: c.ink, width: PEN.outline, arrow: 'ink' });
  g += box(260, 226, '4 · Check independent measurements', ['Hold out a spot target; compare image Ev with the measured Ev.', 'Check clipping, movement, flare and changes in the scene.'], { w: 460, h: 98, pen: PEN.profile, colour: c.azi });
  g += k.path('M400,326 V350 H170 V372', { stroke: c.ink, width: PEN.outline, arrow: 'ink' }) + k.path('M580,326 V350 H810 V372', { stroke: c.ink, width: PEN.outline, arrow: 'ink' });
  g += box(30, 376, 'Daylight / luminance study', ['Compare surfaces and design alternatives.', 'Match view, sky and false-colour scale.'], { w: 400, h: 92 });
  g += box(560, 376, 'Glare · fisheye required', ['Calibrated 180° view at the eye position.', 'Inspect the sources; DGP with evalglare.'], { w: 400, h: 92 });
  const note = k.text(30, 500, 'Archive the original exposures, measurement log, lens profile, calibrated HDR, view and analysis settings together.', { size: 12 });
  return svgDocument(k, { width: 990, height: 515, title: 'Processing and validation workflow for a calibrated HDR', body: k.group('workflow', g) + k.group('note', note) });
}

/** Numbered markers over an iPhone preview, at the saved image coordinates (inline only). */
export function pointsOverlay(width, height, points) {
  const r = Math.max(width, height) / 45;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" class="point-overlay" aria-hidden="true">${points.map(([x, y], i) =>
    `<circle cx="${x}" cy="${y}" r="${r}" fill="#ffffff" stroke="#26333e" stroke-width="${r / 7}"/><text x="${x}" y="${y}" dy=".35em" text-anchor="middle" font-family="Helvetica Neue, Helvetica, Arial, sans-serif" font-size="${r * 1.1}" font-weight="700" fill="#26333e">${i + 1}</text>`).join('')}</svg>`;
}

/** Turbo legend for the false-colour maps: log scale 10–10,000 cd/m², as used by LumiSnap. */
export function luminanceLegend() {
  const stops = Array.from({ length: 17 }, (_, i) => `<stop offset="${(i / 16).toFixed(4)}" stop-color="${turbo(i / 16)}"/>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 14" preserveAspectRatio="none" class="turbo-bar" aria-hidden="true"><defs><linearGradient id="hdr-turbo">${stops}</linearGradient></defs><rect width="400" height="14" rx="2" fill="url(#hdr-turbo)"/></svg>`;
}

